import{c as t,Q as r,j as n,m as a}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"The registration desk","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/registration-desk.md","filePath":"user/running-the-event/registration-desk.md"}'),o={name:"user/running-the-event/registration-desk.md"};function s(i,e,h,d,l,c){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="the-registration-desk" tabindex="-1">The registration desk <a class="header-anchor" href="#the-registration-desk" aria-label="Permalink to &quot;The registration desk&quot;">​</a></h1><p><strong>Audience:</strong> Organisers setting up the entry table, and the volunteers who staff it.</p><p>The registration desk is a cut-down Manager for the entry table. It does the things that table does all day (find somebody, fix their class or card, enter somebody new, hand out hire cards and see what&#39;s still out) and leaves out everything a volunteer could break: settings, devices, the start draw, card downloads, and starting or finishing the event.</p><p>It runs in a browser on a laptop or a tablet, on the same server as the operator&#39;s console, so every change it makes is on every other screen within a second or so. Several desks can run at once.</p><p>This page is the tour of the desk itself. For the work of entering people on the day (what each field needs, start times, someone who isn&#39;t running after all), see <a href="./late-entries">Late entries</a>. For lending cards and other equipment, see <a href="./hire-items">Hire items</a>.</p><h2 id="opening-the-desk" tabindex="-1">Opening the desk <a class="header-anchor" href="#opening-the-desk" aria-label="Permalink to &quot;Opening the desk&quot;">​</a></h2><p>The desk lives at <code>/rego</code> on the server, for example <code>http://192.168.1.20:5154/rego</code>. Take its link from <strong>Settings → Server → Access links</strong> on the operator&#39;s computer: the <strong>Registration</strong> link. <strong>Show QR code</strong> opens it on a tablet without typing.</p><p>Which of the two links to give it:</p><ul><li><strong>A laptop with a card reader</strong>: the <strong>IP</strong> link. It will be running Chrome or Edge (or Firefox 151+) to read the reader, and Chrome often can&#39;t find the server by name. See <a href="./../reference/server-addresses">Reaching the server: name or IP</a>.</li><li><strong>A tablet or phone</strong>: either link works. A tablet can&#39;t use a card reader, so the desk on it is typed into.</li></ul><p>To read cards on a laptop that isn&#39;t the server computer, the desk also needs the secure (HTTPS) link, the same as a download laptop. See <a href="./card-download#before-you-start-browser-and-connection">Downloading cards</a> for the browsers and the connection a reader needs.</p><h3 id="the-pin" tabindex="-1">The PIN <a class="header-anchor" href="#the-pin" aria-label="Permalink to &quot;The PIN&quot;">​</a></h3><p>If Manager has a PIN (<strong>Settings → Access protection</strong>), the desk asks for it before showing anything: type it into <strong>PIN</strong> and press <strong>Unlock</strong>. It&#39;s the same PIN as the manager screens, because the desk changes competitors just as they do.</p><p>When the desk is unlocked, <strong>Lock</strong> in the <strong>⋮</strong> menu signs it out again. Use it whenever you leave the table unattended. Without a PIN, <strong>Lock</strong> isn&#39;t offered and the desk opens straight away. See <a href="./../reference/settings#access-protection">Settings</a>.</p><h3 id="name-this-computer" tabindex="-1">Name this computer <a class="header-anchor" href="#name-this-computer" aria-label="Permalink to &quot;Name this computer&quot;">​</a></h3><p>The first time the desk opens in a browser, it asks you to <strong>Name this computer</strong>, as the manager does. Call it something you&#39;ll recognise later, such as &quot;Entry desk 1&quot;. The name is how the <a href="./../reference/audit-trail#naming-a-computer">audit trail</a> tells two desks apart, and how the operator chooses where this desk&#39;s prints go. <strong>Not now</strong> skips it. The desk has no Settings of its own, so to rename it later, use <strong>Settings → Printing</strong> on the operator&#39;s computer.</p><h3 id="choosing-the-event" tabindex="-1">Choosing the event <a class="header-anchor" href="#choosing-the-event" aria-label="Permalink to &quot;Choosing the event&quot;">​</a></h3><p>The desk opens on <strong>Registration</strong>, a list of the events it could be taking entries for: the running event first, then any event dated today or later that hasn&#39;t been finished. Tap one to open it. The desk never opens an event by itself, even when there&#39;s only one.</p><p>An event that has been finished or abandoned isn&#39;t listed, and an event dated before today isn&#39;t either, unless it&#39;s the one running. If the list is empty, the desk says so: create or start the event in Manager first.</p><p>The flag at the top right of this screen picks the desk&#39;s language. Until a volunteer picks one, the desk follows the language set for the whole installation, and changes with it.</p><h2 id="around-the-desk" tabindex="-1">Around the desk <a class="header-anchor" href="#around-the-desk" aria-label="Permalink to &quot;Around the desk&quot;">​</a></h2><p>The bar across the top shows the event&#39;s name and, while the event is live, the event clock. The clock is the server&#39;s event time, the same as the one behind the start, not the tablet&#39;s own clock. Before the event is started there is no clock.</p><p>Beside the clock:</p><ul><li><strong>The reader icon</strong>: connects a SportIdent reader (see <a href="#reading-cards-at-the-desk">Reading cards at the desk</a>). It isn&#39;t shown on a browser that can&#39;t use one, such as a tablet or phone.</li><li><strong>⋮</strong>: <strong>Switch event</strong>, back to the list of events, and <strong>Lock</strong> when there&#39;s a PIN.</li></ul><p>Two screens sit in the bar along the bottom: <strong>Competitors</strong> and <strong>Hire items</strong>.</p><p>If the desk loses the server, a <strong>Server unavailable — reconnecting…</strong> banner appears across the top. It reconnects by itself and catches up with whatever changed in the meantime. If the desk couldn&#39;t read the event at all, its screens say <strong>Could not read this event</strong> instead of claiming that somebody isn&#39;t entered. Check the network before entering anyone, or you may enter someone who&#39;s already there.</p><p>When the operator finishes the event, the desk goes back to the list of events by itself, so it can&#39;t go on taking entries for a race that&#39;s over.</p><p>The desk&#39;s light or dark theme is set for every desk at once, under <strong>Theme</strong> in <strong>Settings → Appearance → This computer</strong> on the operator&#39;s computer (the <strong>Registration</strong> one).</p><h2 id="competitors" tabindex="-1">Competitors <a class="header-anchor" href="#competitors" aria-label="Permalink to &quot;Competitors&quot;">​</a></h2><p>This is where the desk spends its day. It has one search box (<strong>Find</strong>) and the orange add button beside it. The list stays empty until you type.</p><h3 id="finding-someone" tabindex="-1">Finding someone <a class="header-anchor" href="#finding-someone" aria-label="Permalink to &quot;Finding someone&quot;">​</a></h3><p>Type anything into <strong>Find</strong>: a name or part of one, a card number, a bib, a class or a club. Several words narrow it down: <code>smith m21</code> finds the Smiths in M21. The closest matches come first: an exact card number, then an exact bib, then names starting with what you typed.</p><p>With a reader connected, putting a card on the reader types its number into the search box. If exactly one competitor holds that card, their <strong>Edit competitor</strong> dialog opens straight away.</p><p>When nobody matches, the desk offers <strong>Enter as a new competitor</strong>, with what you typed as their name. When you searched for a card number (five digits or more) that nobody in the event holds, it says <strong>Card <em>number</em> is not entered in this event.</strong> and offers <strong>Add</strong>, with the card number filled in.</p><h3 id="quick-changes-on-the-card" tabindex="-1">Quick changes on the card <a class="header-anchor" href="#quick-changes-on-the-card" aria-label="Permalink to &quot;Quick changes on the card&quot;">​</a></h3><p>Each match is a card showing the competitor&#39;s name, club and status, and three boxes you can change on the spot:</p><ul><li><strong>Class</strong>, including <strong>No class</strong>.</li><li><strong>Card number</strong>, digits only. With the caret in this box, a card put on the reader fills it in for this runner instead of searching. That&#39;s the quickest way to hand over a hire card: find the runner, click in their <strong>Card number</strong>, put the hire card on the reader.</li><li><strong>Notes</strong>, for anything someone needs to know later. See <a href="./../event-setup/competitors-clubs-teams#notes">Notes</a>.</li></ul><p>Changing any of them shows <strong>Revert</strong> and <strong>Save</strong>. Nothing is sent until you press <strong>Save</strong>, and all three changes go together. If the server refuses a change, the desk says why and leaves what you typed in the box, so you can correct it or <strong>Revert</strong>.</p><p>If you change the search while a card still has unsaved changes, the desk stops and asks first (<strong>Unsaved changes</strong>): <strong>Save</strong>, <strong>Revert</strong>, or <strong>Keep editing</strong>. Otherwise the card would drop out of the list and take your change with it.</p><p>The status chip reads the same as on the operator&#39;s screens: whether they&#39;ve started, are on course, or are back with a result. A runner who already has a result can still change class; Manager then scores their run again against the new class&#39;s course.</p><h3 id="the-edit-competitor-dialog" tabindex="-1">The Edit competitor dialog <a class="header-anchor" href="#the-edit-competitor-dialog" aria-label="Permalink to &quot;The Edit competitor dialog&quot;">​</a></h3><p>Tap a competitor&#39;s name (the top part of their card) to open the same <strong>Edit competitor</strong> dialog the operator uses, with all its tabs and rules. It saves each change as you make it, as it does in the manager. See <a href="./../event-setup/competitors-clubs-teams#editing-an-existing-competitor">Editing an existing competitor</a>. The parts the desk is asked about most:</p><ul><li><strong>Details</strong>: name, club, card number, class, and <strong>Course</strong> when the class has a choice of courses. While the dialog is open, a card put on the reader goes into this competitor&#39;s <strong>Card number</strong>.</li><li><strong>Start</strong>: their allocated start time. See <a href="./late-entries#giving-them-a-start-time">Giving them a start time</a>.</li><li><strong>Result</strong>: their status, for example <strong>DNS</strong> for someone who isn&#39;t running after all. See <a href="./late-entries#when-someone-isn-t-running-after-all">When someone isn&#39;t running after all</a>.</li><li><strong>Hire items</strong>: compasses, map boards and anything else you lend, when the organiser has set any up. See <a href="./hire-items#hand-anything-else-over">Hand anything else over</a>.</li><li><strong>Prints</strong>: their splits slip or result label as it would print, with a <strong>Print</strong> button. It prints where this desk&#39;s prints are routed (see <a href="#printing">Printing</a>).</li></ul><p>The desk also shows what has already happened to the runner, such as their radio punches, their download and any corrections, so you can answer &quot;did she get round?&quot; without walking to the operator. It can&#39;t take a download: the <strong>Download</strong> tab shows the card read at the download desk, without the buttons for typing one in by hand.</p><h3 id="adding-someone" tabindex="-1">Adding someone <a class="header-anchor" href="#adding-someone" aria-label="Permalink to &quot;Adding someone&quot;">​</a></h3><p>The add button, <strong>Enter as a new competitor</strong> and <strong>Add</strong> all open the <strong>Add competitor</strong> dialog, the same one the operator uses. A card on the reader fills in its number; if the <a href="./../reference/competitor-registry">Competitor Registry</a> knows whose card it is, it fills in the whole person, leaving you only the class. <strong>Keep adding</strong> clears the form for the next person in a queue. All of this is described in <a href="./late-entries#adding-a-competitor">Adding a competitor</a>.</p><p>The club box offers this event&#39;s clubs and every club in the Club Registry, so a runner from a club nobody else in the event belongs to can still be entered with their club.</p><h2 id="hire-items" tabindex="-1">Hire items <a class="header-anchor" href="#hire-items" aria-label="Permalink to &quot;Hire items&quot;">​</a></h2><p>The second screen shows what you can hand over and who has the rest: the hire cards in the pool, each <strong>Available</strong> or <strong>Out</strong> with the name of whoever holds it, and a summary of each of your other items. Tap anyone holding something to open them. This screen is described in <a href="./hire-items#the-same-box-at-the-registration-desk">The same box, at the registration desk</a>.</p><p>To hand a hire card over, record its number as the runner&#39;s card, on the <strong>Competitors</strong> screen or in their dialog. There&#39;s no separate &quot;hire out&quot; step: a runner holding a pool number is on a hire card. See <a href="./hire-items#hand-a-card-over">Hand a card over</a>.</p><h2 id="reading-cards-at-the-desk" tabindex="-1">Reading cards at the desk <a class="header-anchor" href="#reading-cards-at-the-desk" aria-label="Permalink to &quot;Reading cards at the desk&quot;">​</a></h2><p>A SportIdent reader plugged into the desk&#39;s laptop saves a runner reading seven digits out loud. Click the reader icon in the top bar the first time and pick the reader in the browser&#39;s list. The icon shows a green tick when it&#39;s ready to read. Click it again to disconnect.</p><p><strong>At the desk, the reader only reads a card&#39;s number.</strong> It never downloads the card or records a result, whatever is on the card, so presenting a card that still holds last week&#39;s punches can&#39;t put a result on anybody. Results come from the download desk.</p><p>Where a presented card goes depends on what&#39;s in front of you:</p><table tabindex="0"><thead><tr><th>What&#39;s on screen</th><th>The card&#39;s number goes</th></tr></thead><tbody><tr><td>The <strong>Competitors</strong> screen</td><td>Into <strong>Find</strong>, opening the competitor if exactly one holds it.</td></tr><tr><td>A competitor&#39;s card, with the caret in its <strong>Card number</strong> box</td><td>Into that box, for that runner.</td></tr><tr><td>The <strong>Edit competitor</strong> dialog</td><td>Into that competitor&#39;s <strong>Card number</strong>.</td></tr><tr><td>The <strong>Add competitor</strong> dialog</td><td>Into <strong>Card number</strong>, filling in the person from the registry when it can.</td></tr><tr><td>The <strong>Hire items</strong> screen</td><td>Into its search box, showing that card.</td></tr></tbody></table><p>A desk without a reader works the same way with the number typed in by hand.</p><h2 id="printing" tabindex="-1">Printing <a class="header-anchor" href="#printing" aria-label="Permalink to &quot;Printing&quot;">​</a></h2><p>The desk is one of the server&#39;s computers, like a download laptop, so it can print. The operator chooses where its prints go in <strong>Settings → Printing</strong>, under this desk&#39;s name, and a USB printer plugged into the desk&#39;s laptop can print there. If a print doesn&#39;t come out, the desk is told. See <a href="./splits-printing#where-each-computer-s-splits-and-labels-print">Where each computer&#39;s splits and labels print</a> and <a href="./splits-printing#printing-by-hand-and-reprinting">Printing by hand, and reprinting</a>.</p><h2 id="what-the-desk-can-t-do" tabindex="-1">What the desk can&#39;t do <a class="header-anchor" href="#what-the-desk-can-t-do" aria-label="Permalink to &quot;What the desk can&#39;t do&quot;">​</a></h2><p>The desk leaves out anything the entry table doesn&#39;t need. From the desk you can&#39;t:</p><ul><li>download cards, or type a download in by hand;</li><li>change classes, courses, controls, clubs or the start draw;</li><li>import or export entries, or see results;</li><li>start or finish the event;</li><li>reach Settings, radios, printers or any other device.</li></ul><p>For those, use the manager. The desk keeps a volunteer away from them; it isn&#39;t a lock. The desk uses the same PIN as the manager, so anyone who knows it can open <code>/manager</code> on the same laptop. If you need to keep the manager away from the desk&#39;s volunteers, don&#39;t give them the PIN: unlock the desk for them.</p><p>The <strong>Edit competitor</strong> dialog is the full one, so the desk can do anything to a competitor that the operator can, including setting a status and deleting an entry. Agree with the desk what it handles and what it sends to the operator. See <a href="./../reference/multi-operator-setup#two-people-one-competitor">Two people, one competitor</a>.</p><h2 id="who-changed-what" tabindex="-1">Who changed what <a class="header-anchor" href="#who-changed-what" aria-label="Permalink to &quot;Who changed what&quot;">​</a></h2><p>Every change made at the desk is recorded in the event&#39;s <a href="./../reference/audit-trail">audit trail</a> with the source <strong>Entry desk</strong> and the name of the computer it was made on. To see what the desks changed, filter the Audit trail screen by <strong>Source: Entry desk</strong>.</p><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>The event isn&#39;t in the desk&#39;s list</td><td>It has been finished, or it&#39;s dated before today and isn&#39;t the running event. Check the event&#39;s date and status in Manager.</td></tr><tr><td>There&#39;s no reader icon</td><td>The browser can&#39;t use a reader: a tablet or phone, Safari, or a separate laptop on the plain <code>http</code> link. Use Chrome, Edge or Firefox 151+ on a laptop, on the HTTPS link. See <a href="./card-download#before-you-start-browser-and-connection">Downloading cards</a>.</td></tr><tr><td>The desk won&#39;t load on a laptop</td><td>Use the <strong>IP</strong> link rather than the name. See <a href="./../reference/server-addresses">Reaching the server: name or IP</a>.</td></tr><tr><td>A card on the reader searched instead of going into a runner&#39;s card box</td><td>The caret wasn&#39;t in the box. Click in <strong>Card number</strong> on their card, then present the card again.</td></tr><tr><td>The search won&#39;t change</td><td>A card above has unsaved changes. Answer <strong>Unsaved changes</strong>: <strong>Save</strong> or <strong>Revert</strong>.</td></tr><tr><td><strong>Could not read this event</strong></td><td>The desk has lost the server, or the server refused it. Check the network, and don&#39;t enter anyone until the message clears.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./late-entries">Late entries</a></li><li><a href="./hire-items">Hire items</a></li><li><a href="./../event-setup/competitors-clubs-teams">Competitors and clubs</a></li><li><a href="./../reference/multi-operator-setup">Multi-operator setup</a></li><li><a href="./../reference/server-addresses">Reaching the server: name or IP</a></li><li><a href="./card-download">Downloading cards</a></li><li><a href="./splits-printing">Printing splits</a></li><li><a href="./../reference/audit-trail">Audit trail</a></li></ul>',68)])])}const u=t(o,[["render",s]]);export{p as __pageData,u as default};
